update scenarios set content = '{"characters": {"stranger": "un passant", "you_thought": "narration"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(You approach a stranger on the street to ask for directions.)", "text_fr": "(Vous approchez un inconnu dans la rue pour demander votre chemin.)", "choices": [{"text": "Excuse me, is there a pharmacy nearby?", "text_fr": "Excusez-moi, il y a une pharmacie à proximité ?", "next": "n2"}]}, "n2": {"speaker": "stranger", "text": "Yes, there''s one just two blocks from here, on the left.", "text_fr": "Oui, il y en a une juste à deux rues d''ici, sur la gauche.", "choices": [{"text": "Great, thank you! Is it easy to spot?", "text_fr": "Super, merci ! C''est facile à repérer ?", "next": "n3"}, {"text": "Do you happen to know if it''s open right now?", "text_fr": "Vous savez par hasard si elle est ouverte en ce moment ?", "next": "n3b"}]}, "n3": {"speaker": "stranger", "text": "Yes, it has a big green cross sign, hard to miss.", "text_fr": "Oui, il y a une grande croix verte, difficile à rater.", "choices": [{"text": "Perfect, thank you very much!", "text_fr": "Parfait, merci beaucoup !", "next": "n4"}]}, "n3b": {"speaker": "stranger", "text": "I''m not sure, actually — some pharmacies close for lunch around here.", "text_fr": "Je ne suis pas sûr, en fait — certaines pharmacies ferment pour le déjeuner par ici.", "choices": [{"text": "Good to know, I''ll head over now just in case.", "text_fr": "Bon à savoir, j''y vais tout de suite au cas où.", "next": "n4"}, {"text": "I''ll call ahead first, just to be safe.", "text_fr": "Je vais appeler avant, pour être sûr.", "next": "n_call"}]}, "n_call": {"speaker": "you_thought", "text": "(You call the pharmacy — it''s open until 7pm, no lunch closure today.)", "text_fr": "(Vous appelez la pharmacie — elle est ouverte jusqu''à 19h, pas de fermeture ce midi.)", "choices": [{"text": "Perfect, I''ll head over with peace of mind.", "text_fr": "Parfait, j''y vais l''esprit tranquille.", "next": "end_called"}]}, "n4": {"speaker": "stranger", "text": "You''re welcome, I hope you feel better soon!", "text_fr": "Je vous en prie, j''espère que vous irez mieux bientôt !", "choices": [{"text": "Thank you, have a great day!", "text_fr": "Merci, bonne journée !", "next": "end_found"}]}, "end_found": {"speaker": "you_thought", "text": "(You find the pharmacy easily and get what you need.)", "text_fr": "(Vous trouvez la pharmacie facilement et obtenez ce dont vous avez besoin.)", "end": true, "ending_label": "Pharmacie trouvée sans souci 💊"}, "end_called": {"speaker": "you_thought", "text": "(Thanks to your call, you avoid a wasted trip and arrive at the perfect time.)", "text_fr": "(Grâce à votre appel, vous évitez un trajet inutile et arrivez au bon moment.)", "end": true, "ending_label": "Trajet évité grâce à un appel malin 📞💊"}}}'::jsonb
where title = 'Demander une pharmacie';
